input.content:
/**
 * Reading flow from the rhythm of the keys.
 *
 * Nothing here looks at the words — only at when they arrive and how many are
 * taken back. Five readings:
 *
 *   away      no keys for minutes; nothing should change around the page
 *   working   ordinary writing: pauses, rereads, small cuts
 *   settling  a steady run has begun; the chrome starts to dim
 *   flow      the run has held; the room goes quiet and the page stands alone
 *   stuck     a long pause after cutting and circling — help may land now
 *
 * The readings are sticky on purpose. Entering flow takes a sustained run;
 * leaving it takes a real pause (or the writer reaching for the room), never
 * a single deletion or a glance away. A rewrite inside flow is still flow.
 *
 * Thresholds are not constants: `thresholdsFor` in `flow-profile.ts` derives
 * them from how this writer actually pauses. Pure — `now` is passed in.
 */

export type FlowMode = "away" | "working" | "settling" | "flow" | "stuck";

export interface KeySample {
  at: number;
  inserted: number;
  deleted: number;
}

export interface FlowThresholds {
  /** Longest gap between keys that still counts as one run. */
  gapMs: number;
  /** Run length before the chrome starts to dim. */
  settleMs: number;
  /** Run length before the page goes quiet. */
  flowMs: number;
  /** A pause this long, after churn, reads as stuck. */
  stuckPauseMs: number;
  /** A pause this long ends flow. */
  exitPauseMs: number;
  /** No keys for this long reads as away. */
  awayMs: number;
  /** Share of characters taken back that still counts as steady. */
  maxDeleteRatio: number;
  /** Share of the run's seconds that carried a key. */
  minActiveRatio: number;
}

export const DEFAULT_THRESHOLDS: FlowThresholds = {
  gapMs: 4_000,
  settleMs: 30_000,
  flowMs: 90_000,
  stuckPauseMs: 18_000,
  exitPauseMs: 25_000,
  awayMs: 180_000,
  maxDeleteRatio: 0.3,
  minActiveRatio: 0.45,
};

export interface FlowContext {
  /** 0..1 from `readStruggle` for the paragraph under the cursor. */
  struggle?: number;
  /** The writer has held the pointer over the room (margins, masthead). */
  reaching?: boolean;
}

export interface FlowReading {
  mode: FlowMode;
  /** Length of the current (or last) run, ms. */
  runMs: number;
  /** Time since the last key, ms. */
  pauseMs: number;
  activeRatio: number;
  deleteRatio: number;
  /** Words a minute across the run, at five characters a word. */
  wpm: number;
  /** Deletions over the last minute of writing, as a share of all edits. */
  recentChurn: number;
  reason: string;
}

/** Keep only what `readFlow` can use; call on every sample. */
export function trimSamples(
  samples: KeySample[],
  now: number,
  keepMs = 10 * 60_000,
): KeySample[] {
  const cutoff = now - keepMs;
  let start = 0;
  while (start < samples.length && samples[start].at < cutoff) start++;
  return start ? samples.slice(start) : samples;
}

export function readFlow(
  samples: readonly KeySample[],
  now: number,
  previous: FlowMode,
  t: FlowThresholds = DEFAULT_THRESHOLDS,
  context: FlowContext = {},
): FlowReading {
  const last = samples[samples.length - 1];
  if (!last) return reading("working", 0, Infinity, 0, 0, 0, 0, "No writing yet.");
  const pauseMs = Math.max(0, now - last.at);

  // The current run: walk back while the gaps stay short.
  let first = samples.length - 1;
  while (first > 0 && samples[first].at - samples[first - 1].at <= t.gapMs)
    first--;
  const run = samples.slice(first);
  const runMs = last.at - run[0].at;
  let inserted = 0;
  let deleted = 0;
  const seconds = new Set<number>();
  for (const s of run) {
    inserted += s.inserted;
    deleted += s.deleted;
    seconds.add(Math.floor(s.at / 1000));
  }
  const deleteRatio = deleted / Math.max(1, inserted + deleted);
  const activeRatio =
    runMs < 1000 ? 1 : Math.min(1, seconds.size / Math.ceil(runMs / 1000));
  const wpm = runMs > 0 ? (inserted / 5) * (60_000 / runMs) : 0;

  let recentIn = 0;
  let recentOut = 0;
  for (let i = samples.length - 1; i >= 0 && last.at - samples[i].at <= 60_000; i--) {
    recentIn += samples[i].inserted;
    recentOut += samples[i].deleted;
  }
  const recentChurn = recentOut / Math.max(1, recentIn + recentOut);
  const steady = deleteRatio <= t.maxDeleteRatio && activeRatio >= t.minActiveRatio;
  const at = (mode: FlowMode, reason: string) =>
    reading(mode, runMs, pauseMs, activeRatio, deleteRatio, wpm, recentChurn, reason);

  if (pauseMs >= t.awayMs) return at("away", "No keys for a while.");

  if (previous === "flow") {
    if (context.reaching) return at("working", "Reached for the room.");
    if (pauseMs >= t.exitPauseMs) return at("working", "A long pause ended the run.");
    return at("flow", "Still in the run.");
  }

  const circling = recentChurn >= 0.4 || (context.struggle ?? 0) >= 0.5;
  if (pauseMs >= t.stuckPauseMs && circling)
    return at("stuck", "A long pause after cutting and circling.");
  if (previous === "stuck" && pauseMs >= t.gapMs)
    return at("stuck", "Still paused.");

  if (pauseMs <= t.gapMs && steady) {
    if (runMs >= t.flowMs) return at("flow", "A steady run held.");
    if (runMs >= t.settleMs) return at("settling", "A steady run is building.");
  }
  if (previous === "settling" && pauseMs <= t.gapMs && runMs >= t.settleMs)
    return at("settling", "The run continues.");
  return at("working", steady ? "Writing." : "Revising.");
}

function reading(
  mode: FlowMode,
  runMs: number,
  pauseMs: number,
  activeRatio: number,
  deleteRatio: number,
  wpm: number,
  recentChurn: number,
  reason: string,
): FlowReading {
  return { mode, runMs, pauseMs, activeRatio, deleteRatio, wpm, recentChurn, reason };
}

/** The quiet modes: nothing new may appear around the page. */
export function isQuiet(mode: FlowMode): boolean {
  return mode === "flow" || mode === "settling";
}

/**
 * What Twyne learns about how this writer works.
 *
 * Only rhythms and reactions, never words: how long their runs last, how long
 * they pause between them, how long it takes them to settle, what hours they
 * write, and which kinds of margin help they use versus wave away. Stored on
 * this device only.
 *
 * Two things read it:
 *   - `thresholdsFor` fits the flow detector to the writer. Someone who
 *     habitually pauses 20 seconds to think is not stuck at 20 seconds.
 *   - `kindWeight` ranks margin items. A kind the writer keeps dismissing
 *     sinks; one they open rises. Laplace-smoothed, so it starts neutral and
 *     no single click swings it.
 */
import { DEFAULT_THRESHOLDS, type FlowThresholds } from "./flow-state";

export type ItemOutcome = "shown" | "engaged" | "dismissed";

export interface KindStats {
  shown: number;
  engaged: number;
  dismissed: number;
}

export interface FlowProfile {
  version: 1;
  /** Pauses between runs, ms; most recent last. */
  pauses: number[];
  /** Run lengths, ms. */
  runs: number[];
  /** Run length at the moment flow was confirmed, ms. */
  flowEntries: number[];
  /** Minutes written in each hour of the day, local time. */
  hours: number[];
  kinds: Record<string, KindStats>;
  /** Times the writer switched automatic focus off by hand. */
  overrides: number;
  updatedAt: number;
}

const MAX_SAMPLES = 240;

export function emptyProfile(): FlowProfile {
  return {
    version: 1,
    pauses: [],
    runs: [],
    flowEntries: [],
    hours: Array.from({ length: 24 }, () => 0),
    kinds: {},
    overrides: 0,
    updatedAt: 0,
  };
}

export function normalizeProfile(value: unknown): FlowProfile {
  const base = emptyProfile();
  if (!value || typeof value !== "object") return base;
  const raw = value as Partial<FlowProfile>;
  const numbers = (list: unknown) =>
    Array.isArray(list)
      ? list.filter((n): n is number => typeof n === "number" && isFinite(n))
      : [];
  const hours = numbers(raw.hours);
  return {
    version: 1,
    pauses: numbers(raw.pauses).slice(-MAX_SAMPLES),
    runs: numbers(raw.runs).slice(-MAX_SAMPLES),
    flowEntries: numbers(raw.flowEntries).slice(-MAX_SAMPLES),
    hours: hours.length === 24 ? hours : base.hours,
    kinds: raw.kinds && typeof raw.kinds === "object" ? raw.kinds : {},
    overrides: typeof raw.overrides === "number" ? raw.overrides : 0,
    updatedAt: typeof raw.updatedAt === "number" ? raw.updatedAt : 0,
  };
}

const push = (list: number[], value: number) =>
  [...list, Math.round(value)].slice(-MAX_SAMPLES);

export function recordPause(p: FlowProfile, ms: number, now: number): FlowProfile {
  // Sub-second gaps are typing, and long ones are someone making tea.
  if (ms < 1_500 || ms > 10 * 60_000) return p;
  return { ...p, pauses: push(p.pauses, ms), updatedAt: now };
}

export function recordRun(
  p: FlowProfile,
  ms: number,
  now: number,
  hour = new Date(now).getHours(),
): FlowProfile {
  if (ms < 5_000) return p;
  const hours = [...p.hours];
  hours[hour] = (hours[hour] ?? 0) + ms / 60_000;
  return { ...p, runs: push(p.runs, ms), hours, updatedAt: now };
}

export function recordFlowEntry(p: FlowProfile, runMs: number, now: number): FlowProfile {
  return { ...p, flowEntries: push(p.flowEntries, runMs), updatedAt: now };
}

export function recordOverride(p: FlowProfile, now: number): FlowProfile {
  return { ...p, overrides: p.overrides + 1, updatedAt: now };
}

export function recordItem(
  p: FlowProfile,
  kind: string,
  outcome: ItemOutcome,
  now: number,
): FlowProfile {
  const stats = p.kinds[kind] ?? { shown: 0, engaged: 0, dismissed: 0 };
  return {
    ...p,
    kinds: { ...p.kinds, [kind]: { ...stats, [outcome]: stats[outcome] + 1 } },
    updatedAt: now,
  };
}

export function quantile(values: readonly number[], q: number): number | null {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const index = Math.min(sorted.length - 1, Math.max(0, (sorted.length - 1) * q));
  const lo = Math.floor(index);
  const hi = Math.ceil(index);
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (index - lo);
}

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/**
 * Fit the detector to the writer. Needs a dozen pauses before it trusts
 * them; until then the defaults hold.
 */
export function thresholdsFor(p: FlowProfile): FlowThresholds {
  const t = { ...DEFAULT_THRESHOLDS };
  if (p.pauses.length >= 12) {
    const typical = quantile(p.pauses, 0.75)!;
    const long = quantile(p.pauses, 0.9)!;
    t.stuckPauseMs = clamp(typical * 2, 12_000, 60_000);
    t.exitPauseMs = clamp(long * 1.5, 15_000, 45_000);
  }
  if (p.flowEntries.length >= 5) {
    t.flowMs = clamp(quantile(p.flowEntries, 0.5)!, 60_000, 240_000);
    t.settleMs = Math.round(t.flowMs / 3);
  }
  return t;
}

/** 0.2..1.8 — how much this writer uses help of this kind. Neutral at 1. */
export function kindWeight(p: FlowProfile, kind: string): number {
  const s = p.kinds[kind];
  if (!s) return 1;
  const rate = (s.engaged + 1) / (s.engaged + s.dismissed + 2);
  return clamp(rate * 2, 0.2, 1.8);
}

/** The writer's usual hours, strongest first — for the inspector. */
export function writingHours(p: FlowProfile, top = 3): number[] {
  return p.hours
    .map((minutes, hour) => ({ minutes, hour }))
    .filter((h) => h.minutes > 0)
    .sort((a, b) => b.minutes - a.minutes)
    .slice(0, top)
    .map((h) => h.hour);
}

/**
 * Everything that may come to the margins, and the one rule for when it may.
 *
 * Producers (comments, the room's notes, the Apparatus, the shelf, your other
 * work, the charter, the dossier) hand the conductor `FlowItem`s. They never
 * draw anything themselves. `decideSurface` decides what the writer sees:
 *
 *   flow / settling   nothing new. What is already on the page stays; new
 *                     items wait, and the waiting count is all that shows.
 *   working           a few items, nearest the cursor first.
 *   stuck             the single best item for the paragraph the writer is
 *                     stuck in, and whatever it links to.
 *   away              no change.
 *
 * Pure: the conductor owns time, storage and the DOM.
 */
import type { FlowMode } from "./flow-state";

export type FlowItemKind =
  | "comment"
  | "persona-note"
  | "source"
  | "work"
  | "shelf"
  | "echo"
  | "charter"
  | "amendment";

/** Which margin an item belongs to: the room's voices, or the writer's own. */
export type FlowSide = "room" | "archive";

export const SIDE_FOR: Record<FlowItemKind, FlowSide> = {
  comment: "room",
  "persona-note": "room",
  source: "room",
  work: "room",
  charter: "room",
  amendment: "room",
  shelf: "archive",
  echo: "archive",
};

export const KIND_LABELS: Record<FlowItemKind, string> = {
  comment: "Margin note",
  "persona-note": "From the room",
  source: "From the Apparatus",
  work: "On the shelf",
  shelf: "From your dossier",
  echo: "You wrote",
  charter: "The charter",
  amendment: "Amendment",
};

/** How much a kind matters before the writer's own habits weigh in. */
const BASE_PRIORITY: Record<FlowItemKind, number> = {
  comment: 0.9,
  "persona-note": 0.75,
  charter: 0.7,
  amendment: 0.65,
  source: 0.55,
  echo: 0.55,
  work: 0.5,
  shelf: 0.45,
};

export interface WorkCard {
  medium: "book" | "album" | "song" | "film";
  title: string;
  creator?: string;
  year?: string;
  cover?: string;
  url?: string;
}

export interface FlowItem {
  id: string;
  kind: FlowItemKind;
  /** Passages in this manuscript the item speaks to, verbatim. */
  anchors: string[];
  title: string;
  /** Body text; for a streaming reply, what has arrived so far. */
  body: string;
  byline?: string;
  /** Accent for the card's rule, e.g. a persona's color. */
  color?: string;
  createdAt: number;
  /** Jev's 0..1 read of relevance, when it was asked. */
  relevance?: number;
  streaming?: boolean;
  work?: WorkCard;
  /** For echoes: which folio the passage lives in. */
  folioId?: string;
  folioName?: string;
  url?: string;
  /** Other items this one connects to (drawn as arrows on hover). */
  links?: string[];
  /** Kind-specific payload, e.g. an amendment's field and proposal. */
  data?: Record<string, string>;
}

export interface SurfaceContext {
  mode: FlowMode;
  /** Plain text of the paragraph under the cursor. */
  cursorText: string;
  /** Anchors already on screen, to prefer items the writer can see. */
  visibleAnchors?: ReadonlySet<string>;
  /** Items the writer dismissed; they never come back. */
  dismissed: ReadonlySet<string>;
  /** Items shown before this decision; kept while the page is quiet. */
  shown: ReadonlySet<string>;
  weight: (kind: FlowItemKind) => number;
  now: number;
  /** How many cards the working state allows. Default 3. */
  workingLimit?: number;
}

export interface Surfacing {
  visible: FlowItem[];
  held: number;
  /** One line per item — kept for the diagnostics log. */
  reasons: Record<string, string>;
}

/** 0..1: how much of the item's anchor text is in `text`. */
export function anchorOverlap(item: FlowItem, text: string): number {
  if (!text || !item.anchors.length) return 0;
  const haystack = normalize(text);
  let best = 0;
  for (const anchor of item.anchors) {
    const needle = normalize(anchor);
    if (!needle) continue;
    if (haystack.includes(needle) || needle.includes(haystack)) return 1;
    const words = needle.split(" ").filter((w) => w.length > 3);
    if (!words.length) continue;
    const hits = words.filter((w) => haystack.includes(w)).length;
    best = Math.max(best, hits / words.length);
  }
  return best;
}

const normalize = (s: string) =>
  s.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, " ").replace(/\s+/g, " ").trim();

export function scoreItem(item: FlowItem, context: SurfaceContext): number {
  const ageMin = Math.max(0, (context.now - item.createdAt) / 60_000);
  const freshness = 0.6 + 0.4 * Math.exp(-ageMin / 20);
  const near = anchorOverlap(item, context.cursorText);
  const onScreen = item.anchors.some((a) => context.visibleAnchors?.has(a))
    ? 0.15
    : 0;
  const relevance = item.relevance ?? 0.6;
  return (
    BASE_PRIORITY[item.kind] *
    context.weight(item.kind) *
    freshness *
    (0.5 + relevance) *
    (1 + near + onScreen)
  );
}

export function decideSurface(
  items: readonly FlowItem[],
  context: SurfaceContext,
): Surfacing {
  const reasons: Record<string, string> = {};
  const live = items.filter((item) => {
    if (context.dismissed.has(item.id)) {
      reasons[item.id] = "dismissed";
      return false;
    }
    return true;
  });
  const ranked = live
    .map((item) => ({ item, score: scoreItem(item, context) }))
    .sort((a, b) => b.score - a.score);

  let visible: FlowItem[];
  switch (context.mode) {
    case "flow":
    case "settling":
    case "away":
      // Nothing new arrives; what the writer already had stays put, except
      // in full flow, where the page stands alone.
      visible =
        context.mode === "flow"
          ? []
          : ranked.filter((r) => context.shown.has(r.item.id)).map((r) => r.item);
      for (const { item } of ranked)
        reasons[item.id] ??= visible.includes(item)
          ? "kept: already on the page"
          : `held: ${context.mode}`;
      break;
    case "stuck": {
      const best = ranked.find(
        (r) => anchorOverlap(r.item, context.cursorText) > 0.3,
      ) ?? ranked[0];
      const linked = new Set(best?.item.links ?? []);
      visible = best
        ? [best.item, ...ranked.filter((r) => linked.has(r.item.id)).map((r) => r.item)]
        : [];
      for (const { item, score } of ranked)
        reasons[item.id] = visible.includes(item)
          ? item === best?.item
            ? `stuck: best for this paragraph (${score.toFixed(2)})`
            : "stuck: linked to the best item"
          : "held: one thing at a time while stuck";
      break;
    }
    default: {
      const limit = context.workingLimit ?? 3;
      visible = ranked.slice(0, limit).map((r) => r.item);
      for (const [index, { item, score }] of ranked.entries())
        reasons[item.id] =
          index < limit
            ? `working: rank ${index + 1} (${score.toFixed(2)})`
            : `held: below the top ${limit}`;
    }
  }
  return { visible, held: live.length - visible.length, reasons };
}

/**
 * Stack cards down one margin without overlap. Each card wants to sit level
 * with its anchor; when two collide the later one moves down, and obstacles
 * (the live tool card, the shelf) are stepped around.
 */
export function stackCards(
  cards: ReadonlyArray<{ id: string; top: number; height: number }>,
  obstacles: ReadonlyArray<{ top: number; height: number }> = [],
  gap = 10,
): Record<string, number> {
  const placed: Array<{ top: number; height: number }> = [...obstacles];
  const out: Record<string, number> = {};
  for (const card of [...cards].sort((a, b) => a.top - b.top)) {
    let top = Math.max(0, card.top);
    let moved = true;
    while (moved) {
      moved = false;
      for (const block of placed) {
        const overlaps =
          top < block.top + block.height + gap && top + card.height + gap > block.top;
        if (overlaps) {
          top = block.top + block.height + gap;
          moved = true;
        }
      }
    }
    placed.push({ top, height: card.height });
    out[card.id] = top;
  }
  return out;
}

/**
 * A plain log of what the conductor decided and why — for developers tuning
 * the plumbing, and for writers who want to see what Twyne is reading.
 *
 * Only decisions and numbers: mode changes with their signals, Jev calls
 * with their questions, answers and latency, and which items surfaced or
 * waited. No manuscript text beyond the short previews Jev was handed.
 *
 * Kept in memory for the live view and mirrored to IndexedDB (throttled) so
 * the /house diagnostics tab can read the last session after a navigation.
 */
import { loadMetaFromIdb, saveMetaToIdb, toStorable } from "./idb";

export const FLOW_DIAGNOSTICS_EVENT = "twyne:flow-diagnostics";
const META_KEY = "flow-diagnostics";
const MAX_ENTRIES = 300;

export type DiagnosticKind =
  | "mode"
  | "jev"
  | "surface"
  | "item"
  | "focus"
  | "context"
  | "error";

export interface DiagnosticEntry {
  id: number;
  at: number;
  kind: DiagnosticKind;
  summary: string;
  detail?: Record<string, unknown>;
}

let entries: DiagnosticEntry[] = [];
let counter = 0;
let saveTimer: ReturnType<typeof setTimeout> | undefined;

export function logFlow(
  kind: DiagnosticKind,
  summary: string,
  detail?: Record<string, unknown>,
): void {
  const entry: DiagnosticEntry = {
    id: ++counter,
    at: Date.now(),
    kind,
    summary,
    ...(detail ? { detail } : {}),
  };
  entries = [...entries, entry].slice(-MAX_ENTRIES);
  if (typeof window === "undefined") return;
  window.dispatchEvent(
    new CustomEvent<DiagnosticEntry>(FLOW_DIAGNOSTICS_EVENT, { detail: entry }),
  );
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    void saveMetaToIdb(META_KEY, toStorable(entries));
  }, 2_000);
}

export function flowDiagnostics(): DiagnosticEntry[] {
  return entries;
}

/** The live log, or the last persisted one when this tab has none yet. */
export async function loadFlowDiagnostics(): Promise<DiagnosticEntry[]> {
  if (entries.length) return entries;
  const stored = await loadMetaFromIdb<DiagnosticEntry[]>(META_KEY);
  return Array.isArray(stored) ? stored : [];
}

export async function clearFlowDiagnostics(): Promise<void> {
  entries = [];
  await saveMetaToIdb(META_KEY, []);
}

/**
 * Finding what else in the writer's work a passage touches — locally, before
 * any model is asked.
 *
 * A small TF-IDF over paragraphs: good at "these two passages share unusual
 * words", useless at meaning. That is the point. It narrows thousands of
 * paragraphs to a handful of candidates cheaply and privately, and Jev then
 * reads the handful and says which actually bear on each other.
 */

const STOP = new Set(
  "a about above after again against all am an and any are as at be because been before being below between both but by can could did do does doing down during each few for from further had has have having he her here hers herself him himself his how i if in into is it its itself just me more most my myself no nor not now of off on once only or other our ours ourselves out over own same she should so some such than that the their theirs them themselves then there these they this those through to too under until up very was we were what when where which while who whom why will with would you your yours yourself yourselves also one two may might must shall us like even much many well still yet ever never always often really quite rather".split(
    " ",
  ),
);

export function tokens(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[’']s\b/g, "")
    .split(/[^\p{L}\p{N}]+/u)
    .filter((w) => w.length > 2 && !STOP.has(w) && !/^\d+$/.test(w))
    .map(stem);
}

/** Crude suffix folding, enough that "libraries" meets "library". */
function stem(word: string): string {
  if (word.length > 5 && word.endsWith("ies")) return word.slice(0, -3) + "y";
  if (word.length > 5 && word.endsWith("ing")) return word.slice(0, -3);
  if (word.length > 4 && word.endsWith("ed")) return word.slice(0, -2);
  if (word.length > 3 && word.endsWith("s") && !word.endsWith("ss"))
    return word.slice(0, -1);
  return word;
}

export interface Passage {
  id: string;
  text: string;
  /** Where it lives — a folio id, or the current manuscript. */
  source: string;
  sourceName?: string;
}

interface Indexed extends Passage {
  weights: Map<string, number>;
  norm: number;
}

export interface PassageIndex {
  passages: Indexed[];
  idf: Map<string, number>;
}

export function buildIndex(passages: readonly Passage[]): PassageIndex {
  const df = new Map<string, number>();
  const counted = passages.map((p) => {
    const counts = new Map<string, number>();
    for (const t of tokens(p.text)) counts.set(t, (counts.get(t) ?? 0) + 1);
    for (const t of counts.keys()) df.set(t, (df.get(t) ?? 0) + 1);
    return { passage: p, counts };
  });
  const n = passages.length;
  const idf = new Map<string, number>();
  for (const [t, d] of df) idf.set(t, Math.log(1 + n / d));
  return {
    idf,
    passages: counted.map(({ passage, counts }) => {
      const weights = new Map<string, number>();
      let sum = 0;
      for (const [t, c] of counts) {
        const w = (1 + Math.log(c)) * (idf.get(t) ?? 0);
        weights.set(t, w);
        sum += w * w;
      }
      return { ...passage, weights, norm: Math.sqrt(sum) };
    }),
  };
}

export interface Match {
  passage: Passage;
  score: number;
  /** The rare words the two share, strongest first — shown on the card. */
  shared: string[];
}

export function similar(
  text: string,
  index: PassageIndex,
  options: { k?: number; min?: number; exclude?: (p: Passage) => boolean } = {},
): Match[] {
  const { k = 3, min = 0.12, exclude } = options;
  const query = new Map<string, number>();
  for (const t of tokens(text)) query.set(t, (query.get(t) ?? 0) + 1);
  let qNorm = 0;
  const qWeights = new Map<string, number>();
  for (const [t, c] of query) {
    const w = (1 + Math.log(c)) * (index.idf.get(t) ?? Math.log(2));
    qWeights.set(t, w);
    qNorm += w * w;
  }
  qNorm = Math.sqrt(qNorm);
  if (!qNorm) return [];

  const matches: Match[] = [];
  for (const p of index.passages) {
    if (!p.norm || exclude?.(p)) continue;
    let dot = 0;
    const shared: Array<[string, number]> = [];
    for (const [t, w] of qWeights) {
      const pw = p.weights.get(t);
      if (pw) {
        dot += w * pw;
        shared.push([t, w * pw]);
      }
    }
    // One shared word is a coincidence, not a connection.
    if (shared.length < 2) continue;
    const score = dot / (qNorm * p.norm);
    if (score >= min)
      matches.push({
        passage: { id: p.id, text: p.text, source: p.source, sourceName: p.sourceName },
        score,
        shared: shared.sort((a, b) => b[1] - a[1]).slice(0, 4).map(([t]) => t),
      });
  }
  return matches.sort((a, b) => b.score - a.score).slice(0, k);
}

/** Split plain text into paragraphs worth indexing. */
export function paragraphs(text: string, minChars = 80): string[] {
  return text
    .split(/\n\s*\n|\n/)
    .map((p) => p.replace(/\s+/g, " ").trim())
    .filter((p) => p.length >= minChars);
}

/**
 * Titles a paragraph names: curly- or straight-quoted runs of capitalised
 * words, plus any italic spans the editor hands in. Jev decides later which
 * are real works worth a card.
 */
export function workCandidates(text: string, italics: readonly string[] = []): string[] {
  const found = new Set<string>();
  const quoted = /[“"]([^”"]{2,80})[”"]/g;
  let m: RegExpExecArray | null;
  while ((m = quoted.exec(text))) {
    const title = m[1].trim().replace(/[,.;:!?]+$/, "");
    const words = title.split(/\s+/);
    const capitals = words.filter((w) => /^[\p{Lu}\d]/u.test(w)).length;
    if (words.length <= 9 && capitals >= Math.ceil(words.length / 2)) found.add(title);
  }
  for (const span of italics) {
    const title = span.trim().replace(/[,.;:!?]+$/, "");
    const words = title.split(/\s+/);
    if (words.length >= 1 && words.length <= 9 && /^[\p{Lu}\d]/u.test(title))
      found.add(title);
  }
  return [...found].slice(0, 4);
}

/**
 * Covers for the works a draft names — books from Open Library, records and
 * songs from MusicBrainz with art from the Cover Art Archive.
 *
 * Only the title (and a creator, when the draft gave one) leaves the device,
 * and only when the writer has cover lookups on. Results are cached for the
 * session and MusicBrainz is held to its one-request-a-second rule. Cards
 * show a title, creator, year and cover, and link out — never lyrics.
 */
import { loadMetaFromIdb } from "./idb";
import type { WorkCard } from "./flow-items";

export const COVER_LOOKUP_SETTING_KEY = "flow-cover-lookups";

type Medium = WorkCard["medium"];
type Fetch = typeof fetch;

const cache = new Map<string, WorkCard | null>();
let lastMusicBrainz = 0;

export async function coverLookupsEnabled(): Promise<boolean> {
  return (await loadMetaFromIdb<boolean>(COVER_LOOKUP_SETTING_KEY)) !== false;
}

export async function lookupWork(
  title: string,
  medium: Medium,
  options: { fetchImpl?: Fetch; enabled?: boolean; now?: () => number } = {},
): Promise<WorkCard | null> {
  const enabled = options.enabled ?? (await coverLookupsEnabled());
  if (!enabled || !title.trim() || medium === "film") return null;
  const key = `${medium}:${title.trim().toLowerCase()}`;
  if (cache.has(key)) return cache.get(key) ?? null;
  const fetchImpl = options.fetchImpl ?? fetch;
  let card: WorkCard | null = null;
  try {
    card =
      medium === "book"
        ? await openLibrary(title, fetchImpl)
        : await musicBrainz(title, medium, fetchImpl, options.now ?? Date.now);
  } catch {
    card = null;
  }
  cache.set(key, card);
  return card;
}

async function openLibrary(title: string, fetchImpl: Fetch): Promise<WorkCard | null> {
  const url = `https://openlibrary.org/search.json?${new URLSearchParams({
    q: title,
    limit: "1",
    fields: "key,title,author_name,first_publish_year,cover_i",
  })}`;
  const response = await fetchImpl(url, { headers: { Accept: "application/json" } });
  if (!response.ok) return null;
  const body = (await response.json()) as {
    docs?: Array<{
      key?: string;
      title?: string;
      author_name?: string[];
      first_publish_year?: number;
      cover_i?: number;
    }>;
  };
  const doc = body.docs?.[0];
  if (!doc?.title || !similarTitle(doc.title, title)) return null;
  return {
    medium: "book",
    title: doc.title,
    creator: doc.author_name?.[0],
    year: doc.first_publish_year ? String(doc.first_publish_year) : undefined,
    cover: doc.cover_i
      ? `https://covers.openlibrary.org/b/id/${doc.cover_i}-M.jpg`
      : undefined,
    url: doc.key ? `https://openlibrary.org${doc.key}` : undefined,
  };
}

async function musicBrainz(
  title: string,
  medium: "album" | "song",
  fetchImpl: Fetch,
  now: () => number,
): Promise<WorkCard | null> {
  const wait = lastMusicBrainz + 1_100 - now();
  if (wait > 0) await new Promise((resolve) => setTimeout(resolve, wait));
  lastMusicBrainz = now();
  const entity = medium === "album" ? "release-group" : "recording";
  const url = `https://musicbrainz.org/ws/2/${entity}/?${new URLSearchParams({
    query: medium === "album" ? `releasegroup:"${title}"` : `recording:"${title}"`,
    limit: "1",
    fmt: "json",
  })}`;
  const response = await fetchImpl(url, { headers: { Accept: "application/json" } });
  if (!response.ok) return null;
  const body = (await response.json()) as {
    "release-groups"?: MbItem[];
    recordings?: Array<MbItem & { releases?: Array<{ "release-group"?: { id?: string; title?: string } }> }>;
  };
  const item =
    medium === "album" ? body["release-groups"]?.[0] : body.recordings?.[0];
  if (!item?.title || !similarTitle(item.title, title)) return null;
  const group =
    medium === "album"
      ? item.id
      : (item as { releases?: Array<{ "release-group"?: { id?: string } }> })
          .releases?.[0]?.["release-group"]?.id;
  return {
    medium,
    title: item.title,
    creator: item["artist-credit"]?.[0]?.name,
    year: item["first-release-date"]?.slice(0, 4) || undefined,
    cover: group
      ? `https://coverartarchive.org/release-group/${group}/front-250`
      : undefined,
    url: item.id
      ? `https://musicbrainz.org/${entity}/${item.id}`
      : undefined,
  };
}

interface MbItem {
  id?: string;
  title?: string;
  "first-release-date"?: string;
  "artist-credit"?: Array<{ name?: string }>;
}

/** Search engines always return something; only keep a real match. */
export function similarTitle(found: string, wanted: string): boolean {
  const norm = (s: string) =>
    s.toLowerCase().replace(/^(the|a|an)\s+/, "").replace(/[^\p{L}\p{N}]+/gu, "");
  const a = norm(found);
  const b = norm(wanted);
  return !!a && !!b && (a === b || a.startsWith(b) || b.startsWith(a));
}

export function __resetMediaCacheForTests(): void {
  cache.clear();
  lastMusicBrainz = 0;
}

