  loadFolioContentFromIdb,
  loadFoliosFromIdb,
  loadMetaFromIdb,
  saveMetaToIdb,
  toStorable,
} from "../../../utils/idb";
import { htmlToPlainText } from "../../../utils/anti-tabula-rasa";
import { loadUserComments } from "../../../utils/user-comments";
import { loadBibliographyForFolio } from "../../../utils/bibliography";
import {
  isQuiet,
  readFlow,
  trimSamples,
  type FlowMode,
  type FlowReading,
  type KeySample,
} from "../../../utils/flow-state";
import {
  emptyProfile,
  kindWeight,
  normalizeProfile,
  recordFlowEntry,
  recordItem,
  recordOverride,
  recordPause,
  recordRun,
  thresholdsFor,
  type FlowProfile,
} from "../../../utils/flow-profile";
import {
