/* ── Flow: the margins the conductor fills ─────────────────────────
   Room on the right (notes, replies, sources, works, the charter),
   the writer's own archive on the left. Cards are index slips pinned
   level with their passage; hover draws a proofreader's bracket and a
   pencil line from slip to text. */
.flow-surface {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.flow-surface > * {
  pointer-events: auto;
}
.flow-overlay {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none !important;
}
.flow-overlay__line,
.flow-overlay__bracket {
  fill: none;
  stroke-width: 1.25;
  stroke-linecap: round;
  opacity: 0.8;
}
.flow-overlay__line {
  stroke-dasharray: 600;
  stroke-dashoffset: 600;
  animation: flow-draw 420ms ease-out forwards;
}
.flow-overlay__line.is-dashed {
  stroke-dasharray: 3 4;
  stroke-dashoffset: 0;
  animation: none;
  opacity: 0.55;
}
.flow-overlay__mark {
  opacity: 0.45;
}
@keyframes flow-draw {
  to {
    stroke-dashoffset: 0;
  }
}
.flow-column {
  position: absolute;
  top: 0;
  bottom: 0;
}
.flow-column--room {
  left: calc(100% + 28px);
}
.flow-column--archive {
  right: calc(100% + 28px);
}
.flow-card {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  padding: 0.65rem 0.75rem 0.6rem;
  background: var(--color-paper);
  border: 1px solid var(--color-paper-3);
  border-top: 3px solid var(--flow-accent, var(--color-sage));
  border-radius: 1px;
  color: var(--color-ink);
  font: 0.84rem/1.5 var(--font-serif);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 10px 22px -18px rgb(0 0 0 / 0.45);
  transition:
    top 220ms cubic-bezier(0.2, 0.7, 0.2, 1),
    transform 160ms ease,
    box-shadow 160ms ease;
  animation: flow-slip-in 280ms ease-out;
}
.flow-column--archive .flow-card {
  border-top-width: 1px;
  border-left: 3px solid var(--flow-accent, var(--color-cobalt));
  background: color-mix(in srgb, var(--color-paper) 88%, var(--color-cobalt) 4%);
}
.flow-card.is-hovered {
  transform: translateY(-1px);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 14px 28px -16px rgb(0 0 0 / 0.5);
  z-index: 3;
}
@keyframes flow-slip-in {
  from {
    opacity: 0;
    transform: translateX(10px);
  }
}
.flow-column--archive .flow-card {
  animation-name: flow-slip-in-left;
}
@keyframes flow-slip-in-left {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
}
.flow-card__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}
.flow-card__kicker {
  font: 0.62rem/1.2 var(--font-typewriter);
