}
.flow-card__title {
  font-family: var(--font-display);
  font-size: 0.86rem;
  font-weight: 700;
  line-height: 1.3;
}
.flow-card__text {
  color: var(--color-ink-light);
}
/* An echo reads as a carbon copy of the writer's own page. */
.flow-card__carbon {
  font-family: var(--font-typewriter);
  font-size: 0.72rem;
  line-height: 1.55;
  color: color-mix(in srgb, var(--color-cobalt) 70%, var(--color-ink));
  opacity: 0.9;
}
.flow-card__reply {
  margin: 0;
  padding: 0.45rem 0 0 0.6rem;
  border-left: 1px solid var(--flow-accent, var(--color-paper-3));
  color: var(--color-ink);
  font-style: italic;
}
.flow-card__reply-by {
  display: block;
  font: normal 0.6rem/1.3 var(--font-typewriter);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.flow-card__reply.is-streaming::after {
  content: "▍";
  margin-left: 1px;
  color: var(--flow-accent, var(--color-ink));
  animation: flow-caret 1s steps(2) infinite;
}
@keyframes flow-caret {
  50% {
    opacity: 0;
  }
}
.flow-card__foot {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  font: 0.62rem/1.3 var(--font-typewriter);
  color: var(--color-ink-muted);
}
.flow-card__notice {
  margin: 0;
  font-size: 0.72rem;
  color: var(--color-ink-muted);
}
.flow-link {
  border: 0;
  padding: 0;
  background: none;
  color: var(--color-cobalt);
  font: 0.7rem var(--font-typewriter);
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}
.flow-link:disabled {
  opacity: 0.5;
  cursor: default;
}
.flow-mini {
  padding: 0.15rem 0.6rem;
  font-size: 0.72rem;
}
/* A rubber stamp, slightly askew, for the charter and amendments. */
.flow-stamp {
  position: absolute;
  top: 0.55rem;
  right: 1.6rem;
  padding: 0.05rem 0.35rem;
  border: 1.5px solid var(--color-vermilion);
  border-radius: 2px;
  color: var(--color-vermilion);
  font: 0.58rem/1.3 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transform: rotate(-4deg);
  opacity: 0.75;
  mix-blend-mode: multiply;
}
.flow-amend {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.flow-amend__input {
  width: 100%;
  padding: 0.4rem 0.5rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
  color: var(--color-ink);
  font: 0.8rem/1.45 var(--font-typewriter);
  resize: vertical;
}
.flow-amend__input:focus {
  outline: 1px solid var(--color-vermilion);
}
.flow-amend__actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
/* Works: a book stands upright; a record sits in its sleeve with the
   disc peeking out. */
.flow-work {
  display: flex;
  gap: 0.7rem;
  color: inherit;
  text-decoration: none;
}
.flow-work__sleeve {
  position: relative;
  flex-shrink: 0;
}
.flow-work__sleeve img,
.flow-work__blank {
  position: relative;
  z-index: 1;
  display: block;
  width: 72px;
  object-fit: cover;
  background: var(--color-paper-2);
  box-shadow:
    1px 1px 0 var(--color-paper-3),
    3px 5px 10px -6px rgb(0 0 0 / 0.5);
}
.flow-work--book .flow-work__sleeve img,
.flow-work--book .flow-work__blank {
  height: 108px;
  border-radius: 1px 3px 3px 1px;
}
.flow-work--album .flow-work__sleeve img,
.flow-work--song .flow-work__sleeve img,
.flow-work--album .flow-work__blank,
.flow-work--song .flow-work__blank {
  height: 72px;
}
.flow-work__blank {
  display: grid;
  place-items: center;
  font: 700 1.6rem var(--font-display);
  color: var(--color-ink-muted);
}
.flow-work__disc {
  position: absolute;
  top: 4px;
  left: 18px;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background:
    radial-gradient(circle, var(--color-mustard) 0 14%, #111 15% 17%, transparent 18%),
    repeating-radial-gradient(circle, #1a1a1a 0 1px, #262626 1px 3px);
  transition: transform 240ms ease;
}
.flow-work:hover .flow-work__disc {
  transform: translateX(14px) rotate(40deg);
}
.flow-work__text {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}
.flow-work__medium {
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.flow-work__text strong {
  font-family: var(--font-display);
  line-height: 1.25;
}
.flow-work__text span:last-child {
  font-size: 0.76rem;
  color: var(--color-ink-light);
}
.flow-waiting {
  position: absolute;
  left: 0;
  padding: 0.2rem 0.55rem;
  border: 1px dashed var(--color-paper-3);
  border-radius: 999px;
  background: var(--color-paper);
  color: var(--color-ink-muted);
  font: 0.64rem var(--font-typewriter);
  letter-spacing: 0.05em;
  cursor: pointer;
  transition: top 220ms ease;
}
.flow-waiting:hover {
  color: var(--color-ink);
  border-style: solid;
}
.flow-dock {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: var(--z-dropdown);
  width: min(300px, calc(100vw - 32px));
  pointer-events: auto;
}
.flow-dock .flow-card {
  position: relative;
}
.flow-dock__more {
  margin: 0.3rem 0 0;
  font: 0.62rem var(--font-typewriter);
  color: var(--color-ink-muted);
  text-align: right;
}

/* The chrome eases out as a run builds and stays out in flow. The page
   itself never moves. */
[data-flow="settling"] .editor-workspace-main > header,
[data-flow="settling"] .twyne-toolbar,
[data-flow="settling"] .in-flow-rails,
[data-flow="settling"] .flow-surface {
  opacity: 0.4;
  transition: opacity 1.2s ease;
}
[data-flow="flow"] .flow-surface,
[data-flow="flow"] .in-flow-rails {
  opacity: 0;
