import { describe, expect, test } from "bun:test";
import {
  DEFAULT_THRESHOLDS,
  readFlow,
  trimSamples,
  type KeySample,
} from "./flow-state";

/** One sample every `every` ms for `ms`, typing `chars` and deleting `del`. */
function typing(
  start: number,
  ms: number,
  { every = 400, chars = 3, del = 0 } = {},
): KeySample[] {
  const out: KeySample[] = [];
  for (let at = start; at <= start + ms; at += every)
    out.push({ at, inserted: chars, deleted: del });
  return out;
}

describe("readFlow", () => {
  test("a short run is ordinary writing", () => {
    const samples = typing(0, 10_000);
    expect(readFlow(samples, 10_500, "working").mode).toBe("working");
  });

  test("a steady run settles, then holds as flow", () => {
    const samples = typing(0, 120_000);
    expect(readFlow(samples, 40_000, "working").mode).toBe("settling");
    expect(readFlow(samples, 120_200, "settling").mode).toBe("flow");
  });

  test("heavy deleting never counts as flow", () => {
    const samples = typing(0, 120_000, { chars: 2, del: 2 });
    expect(readFlow(samples, 120_200, "working").mode).toBe("working");
  });

  test("flow survives a short pause and a burst of cutting", () => {
    const samples = [
      ...typing(0, 100_000),
      ...typing(106_000, 3_000, { chars: 0, del: 8 }),
    ];
    expect(readFlow(samples, 110_000, "flow").mode).toBe("flow");
  });

  test("a long pause ends flow", () => {
    const samples = typing(0, 100_000);
    const r = readFlow(samples, 100_000 + DEFAULT_THRESHOLDS.exitPauseMs + 1, "flow");
    expect(r.mode).toBe("working");
  });

  test("reaching for the room ends flow at once", () => {
    const samples = typing(0, 100_000);
    expect(readFlow(samples, 100_500, "flow", DEFAULT_THRESHOLDS, { reaching: true }).mode).toBe(
      "working",
    );
  });

  test("a long pause after cutting reads as stuck", () => {
    const samples = typing(0, 30_000, { chars: 1, del: 2 });
    const r = readFlow(samples, 30_000 + DEFAULT_THRESHOLDS.stuckPauseMs + 1, "working");
    expect(r.mode).toBe("stuck");
  });

  test("a long pause after clean writing is not stuck", () => {
    const samples = typing(0, 30_000);
    const r = readFlow(samples, 30_000 + DEFAULT_THRESHOLDS.stuckPauseMs + 1, "working");
    expect(r.mode).toBe("working");
  });

  test("struggle on the paragraph counts as circling", () => {
    const samples = typing(0, 20_000);
    const r = readFlow(
      samples,
      20_000 + DEFAULT_THRESHOLDS.stuckPauseMs + 1,
      "working",
      DEFAULT_THRESHOLDS,
      { struggle: 0.7 },
    );
    expect(r.mode).toBe("stuck");
  });

  test("minutes without keys read as away", () => {
    const samples = typing(0, 5_000);
    expect(readFlow(samples, 5_000 + DEFAULT_THRESHOLDS.awayMs, "working").mode).toBe("away");
  });
});

test("trimSamples drops only what is older than the window", () => {
  const samples = typing(0, 20_000, { every: 1_000 });
  expect(trimSamples(samples, 20_000, 5_000).map((s) => s.at)).toEqual([
    15_000, 16_000, 17_000, 18_000, 19_000, 20_000,
  ]);
});

import { describe, expect, test } from "bun:test";
import {
  emptyProfile,
  kindWeight,
  normalizeProfile,
  quantile,
  recordItem,
  recordPause,
  recordRun,
  thresholdsFor,
  writingHours,
} from "./flow-profile";
import { DEFAULT_THRESHOLDS } from "./flow-state";

describe("thresholdsFor", () => {
  test("keeps the defaults until it has seen enough pauses", () => {
    let p = emptyProfile();
    for (let i = 0; i < 5; i++) p = recordPause(p, 30_000, i);
    expect(thresholdsFor(p)).toEqual(DEFAULT_THRESHOLDS);
  });

  test("a writer who pauses long to think is given longer before stuck", () => {
    let p = emptyProfile();
    for (let i = 0; i < 20; i++) p = recordPause(p, 20_000, i);
    const t = thresholdsFor(p);
    expect(t.stuckPauseMs).toBe(40_000);
    expect(t.exitPauseMs).toBe(30_000);
  });

  test("clamps a quick writer's thresholds to sane floors", () => {
    let p = emptyProfile();
    for (let i = 0; i < 20; i++) p = recordPause(p, 2_000, i);
    expect(thresholdsFor(p).stuckPauseMs).toBe(12_000);
  });
});

describe("kindWeight", () => {
  test("is neutral for a kind never seen", () => {
    expect(kindWeight(emptyProfile(), "echo")).toBe(1);
  });

  test("sinks for a kind the writer keeps dismissing, rises for one they use", () => {
    let p = emptyProfile();
    for (let i = 0; i < 8; i++) p = recordItem(p, "work", "dismissed", i);
    for (let i = 0; i < 8; i++) p = recordItem(p, "comment", "engaged", i);
    expect(kindWeight(p, "work")).toBeLessThan(0.5);
    expect(kindWeight(p, "comment")).toBeGreaterThan(1.5);
  });
});

test("ignores typing gaps and tea breaks when learning pauses", () => {
  let p = emptyProfile();
  p = recordPause(p, 400, 0);
  p = recordPause(p, 20 * 60_000, 0);
  expect(p.pauses).toEqual([]);
});

test("remembers the hours a writer writes", () => {
  let p = emptyProfile();
  p = recordRun(p, 30 * 60_000, 0, 6);
  p = recordRun(p, 10 * 60_000, 0, 22);
  expect(writingHours(p)).toEqual([6, 22]);
});

test("normalizeProfile survives junk from storage", () => {
  const p = normalizeProfile({ pauses: ["x", 3000], hours: [1], kinds: null });
  expect(p.pauses).toEqual([3000]);
  expect(p.hours).toHaveLength(24);
  expect(p.kinds).toEqual({});
});

test("quantile interpolates", () => {
  expect(quantile([1, 2, 3, 4], 0.5)).toBe(2.5);
  expect(quantile([], 0.5)).toBeNull();
});

import { describe, expect, test } from "bun:test";
import {
  anchorOverlap,
  decideSurface,
  stackCards,
  type FlowItem,
  type SurfaceContext,
} from "./flow-items";

const item = (id: string, kind: FlowItem["kind"], anchor: string, extra: Partial<FlowItem> = {}): FlowItem => ({
  id,
  kind,
  anchors: [anchor],
  title: id,
  body: "",
  createdAt: 0,
  ...extra,
});

const context = (overrides: Partial<SurfaceContext> = {}): SurfaceContext => ({
  mode: "working",
  cursorText: "The library budget is civic infrastructure, not charity.",
  dismissed: new Set(),
  shown: new Set(),
  weight: () => 1,
  now: 0,
  ...overrides,
});

const items = [
  item("near", "comment", "library budget is civic infrastructure"),
  item("far", "comment", "an unrelated passage about harbour cranes"),
  item("echo", "echo", "civic infrastructure", { links: ["near"] }),
  item("work", "work", "Palaces for the People"),
];

describe("decideSurface", () => {
  test("flow shows nothing and holds everything", () => {
    const s = decideSurface(items, context({ mode: "flow", shown: new Set(["near"]) }));
    expect(s.visible).toEqual([]);
    expect(s.held).toBe(items.length);
  });

  test("settling keeps what was already on the page but lets nothing new in", () => {
    const s = decideSurface(items, context({ mode: "settling", shown: new Set(["far"]) }));
    expect(s.visible.map((i) => i.id)).toEqual(["far"]);
  });

  test("working shows a few, nearest the cursor first", () => {
    const s = decideSurface(items, context({ workingLimit: 2 }));
    expect(s.visible[0].id).toBe("near");
    expect(s.visible).toHaveLength(2);
    expect(s.held).toBe(2);
  });

  test("stuck shows the best item for the paragraph and what it links to", () => {
    const s = decideSurface(items, context({ mode: "stuck" }));
    expect(s.visible.map((i) => i.id).sort()).toEqual(["echo", "near"].sort().filter(Boolean).length === 2 ? ["echo", "near"] : []);
  });

  test("a dismissed item never returns", () => {
    const s = decideSurface(items, context({ dismissed: new Set(["near"]) }));
    expect(s.visible.map((i) => i.id)).not.toContain("near");
    expect(s.reasons.near).toBe("dismissed");
  });

  test("the writer's habits reorder kinds", () => {
    const s = decideSurface(
      [item("a", "comment", "harbour"), item("b", "work", "harbour")],
      context({ cursorText: "", weight: (k) => (k === "comment" ? 0.2 : 1.8) }),
    );
    expect(s.visible[0].id).toBe("b");
  });
});

test("anchorOverlap matches containment and partial wording", () => {
  expect(anchorOverlap(items[0], context().cursorText)).toBe(1);
  expect(anchorOverlap(items[1], context().cursorText)).toBe(0);
});

describe("stackCards", () => {
  test("keeps cards level with their anchors when they fit", () => {
    expect(stackCards([{ id: "a", top: 10, height: 50 }, { id: "b", top: 200, height: 50 }])).toEqual({
      a: 10,
      b: 200,
    });
  });

  test("pushes a colliding card below the one above it", () => {
    const tops = stackCards([
      { id: "a", top: 10, height: 100 },
      { id: "b", top: 40, height: 50 },
    ]);
    expect(tops.b).toBe(120);
  });

  test("steps around obstacles", () => {
    const tops = stackCards([{ id: "a", top: 20, height: 40 }], [{ top: 0, height: 100 }]);
    expect(tops.a).toBe(110);
  });
});

import { describe, expect, test } from "bun:test";
import {
  buildIndex,
  paragraphs,
  similar,
  tokens,
  workCandidates,
} from "./flow-connections";

describe("similar", () => {
  const index = buildIndex([
    {
      id: "a",
      source: "f1",
      text: "Branch libraries are civic infrastructure: the reading room is where a city keeps its public quiet.",
    },
    {
      id: "b",
      source: "f2",
      text: "The harbour cranes were painted orange in 1971, and nobody remembers why the council chose it.",
    },
    {
      id: "c",
      source: "f3",
      text: "A library budget is a vote on who gets a public room with heat and light in winter.",
    },
  ]);

  test("finds passages that share unusual words", () => {
    const matches = similar(
      "Cutting the library budget closes the one public room some residents have.",
      index,
      { min: 0.05 },
    );
    expect(matches[0]?.passage.id).toBe("c");
    expect(matches.map((m) => m.passage.id)).not.toContain("b");
    expect(matches[0].shared).toContain("public");
  });

  test("never connects on a single shared word", () => {
    expect(similar("Orange is a colour.", index, { min: 0 })).toEqual([]);
  });

  test("respects exclusions", () => {
    const matches = similar("library budget public room", index, {
      min: 0,
      exclude: (p) => p.id === "c",
    });
    expect(matches.map((m) => m.passage.id)).not.toContain("c");
  });
});

test("tokens drop stop words and fold plurals", () => {
  expect(tokens("The libraries were reading rooms")).toEqual(["library", "read", "room"]);
});

test("paragraphs keep only substantial blocks", () => {
  expect(paragraphs(`Short.\n\n${"A longer paragraph ".repeat(6)}`)).toHaveLength(1);
});

describe("workCandidates", () => {
  test("picks up quoted titles and italic spans", () => {
    const found = workCandidates(
      "She had “Palaces for the People” open and was humming “A Love Supreme”, but said “it was fine, really”.",
      ["Middlemarch"],
    );
    expect(found).toContain("Palaces for the People");
    expect(found).toContain("A Love Supreme");
    expect(found).toContain("Middlemarch");
    expect(found).not.toContain("it was fine, really");
  });
});

