/* The House — a publishing house's front office, c. 1950: a letterhead,
   a filing cabinet, a typed sheet in the platen, a register in the back.
   Every colour is a theme token, so the dark and cool presets carry it. */

.house {
  min-height: 100vh;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font-family: var(--font-serif);
}
.house__inner {
  max-width: 76rem;
  margin: 0 auto;
  padding: 2rem 1.5rem 5rem;
}
@media (max-width: 640px) {
  .house__inner {
    padding: 1.25rem 1rem 4rem;
  }
}

/* ── Letterhead ─────────────────────────────────────────────────── */
.house-letterhead {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 3px double var(--color-ink);
}
.house-letterhead__eyebrow {
  font: 0.62rem/1 var(--font-typewriter);
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-letterhead__name {
  display: block;
  width: 100%;
  margin-top: 0.4rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 clamp(1.8rem, 4vw, 2.75rem) / 1.05 var(--font-display);
  letter-spacing: -0.01em;
}
.house-letterhead__name:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-letterhead__name::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.6;
}
.house-letterhead__motto {
  margin-top: 0.35rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-letterhead__actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}
@media (max-width: 640px) {
  .house-letterhead {
    grid-template-columns: 1fr;
  }
  .house-letterhead__actions {
    justify-content: flex-start;
  }
}

/* ── Tabs, as index-card dividers ───────────────────────────────── */
.house-tabs {
  display: flex;
  gap: 0.25rem;
  margin-top: 1.5rem;
  border-bottom: 1px solid var(--color-paper-3);
  overflow-x: auto;
  scrollbar-width: none;
}
.house-tab {
  position: relative;
  flex-shrink: 0;
  padding: 0.55rem 1rem 0.5rem;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 6px 6px 0 0;
  background: none;
  color: var(--color-ink-muted);
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
}
.house-tab:hover {
  color: var(--color-ink);
}
.house-tab[aria-selected="true"] {
  margin-bottom: -1px;
  border-color: var(--color-paper-3);
  background: var(--color-paper);
  color: var(--color-ink);
}
.house-tab__count {
  margin-left: 0.4rem;
  color: var(--color-vermilion);
}

/* ── Cabinet layout: diagram left, sheet right ──────────────────── */
.house-cabinet {
  display: grid;
  grid-template-columns: minmax(18rem, 26rem) 1fr;
  gap: 2rem;
  padding-top: 1.75rem;
}
@media (max-width: 900px) {
  .house-cabinet {
    grid-template-columns: 1fr;
  }
}

/* ── The diagram ────────────────────────────────────────────────── */
.house-diagram {
  position: sticky;
  top: 1.25rem;
  align-self: start;
}
@media (max-width: 900px) {
  .house-diagram {
    position: static;
  }
}
.house-diagram__caption {
  margin: 0 0 0.75rem;
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-tree {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
/* Letterhead node */
.house-node {
  position: relative;
  display: block;
  width: 100%;
  padding: 0.7rem 0.85rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-paper);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    transform 140ms ease,
    box-shadow 140ms ease,
    border-color 140ms ease;
}
.house-node:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node[aria-current="true"] {
  border-color: var(--color-ink);
  box-shadow:
    inset 0 0 0 1px var(--color-ink),
    0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node__kind {
  display: block;
  font: 0.56rem var(--font-typewriter);
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-node__name {
  display: block;
  margin-top: 0.15rem;
  font: 700 1rem/1.2 var(--font-display);
}
.house-node__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.4rem;
}
.house-node--house {
  border-top: 4px solid var(--color-vermilion);
  background: linear-gradient(
    var(--color-paper),
    color-mix(in srgb, var(--color-paper) 92%, var(--color-vermilion) 3%)
  );
}
/* A collection is a cabinet drawer: brass label holder, pull. */
.house-drawer {
  position: relative;
  margin-left: 1.1rem;
}
.house-drawer::before {
  content: "";
  position: absolute;
  left: -0.75rem;
  top: -0.6rem;
  bottom: 1.2rem;
  border-left: 1px dashed var(--color-ink-muted);
  opacity: 0.6;
}
.house-node--collection {
  padding-left: 2.6rem;
  background: var(--color-paper-2);
  border-bottom-width: 3px;
}
.house-node--collection::before {
  /* the label holder */
  content: "";
  position: absolute;
  left: 0.75rem;
  top: 50%;
  width: 1.1rem;
  height: 0.7rem;
  transform: translateY(-50%);
  border: 1.5px solid var(--color-mustard);
  border-radius: 1px;
  background: color-mix(in srgb, var(--color-mustard) 12%, transparent);
}
.house-node--loose {
  border-style: dashed;
  background: transparent;
}
.house-node--loose::before {
  border-color: var(--color-ink-muted);
  background: none;
}
/* Folios are manila folders with a tab, standing in the drawer. */
.house-folders {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0.35rem 0 0.2rem 1.2rem;
}
.house-folder {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.45rem 0.6rem 0.4rem;
  margin-top: 0.35rem;
  border: 1px solid color-mix(in srgb, var(--color-mustard) 45%, var(--color-paper-3));
  border-radius: 0 3px 3px 3px;
  background: color-mix(in srgb, var(--color-paper) 82%, var(--color-mustard) 14%);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform 140ms ease;
}
.house-folder::before {
  /* the tab */
  content: "";
  position: absolute;
  left: -1px;
  top: -0.4rem;
  width: 2.6rem;
  height: 0.4rem;
  border: inherit;
  border-bottom: 0;
  border-radius: 3px 3px 0 0;
  background: inherit;
}
.house-folder:hover {
  transform: translateX(2px);
}
.house-folder[aria-current="true"] {
  border-color: var(--color-ink);
}
.house-folder__name {
  font: 0.86rem/1.25 var(--font-display);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.house-folder__marks {
  display: flex;
  gap: 0.25rem;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-folder__empty {
  margin: 0.2rem 0 0;
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Chips: typed tags */
.house-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.05rem 0.4rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  background: var(--color-paper-soft);
  font: 0.6rem/1.5 var(--font-typewriter);
  letter-spacing: 0.04em;
  color: var(--color-ink-light);
}
.house-chip--must {
  border-color: color-mix(in srgb, var(--color-vermilion) 50%, transparent);
  color: var(--color-vermilion);
}

/* The legend under the tree: how the stack pours down. */
.house-legend {
  margin-top: 1.25rem;
  padding: 0.85rem 0.9rem;
  border: 1px dashed var(--color-paper-3);
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--color-ink-light);
}
.house-legend dt {
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink);
}
.house-legend dd {
  margin: 0.1rem 0 0.55rem;
}
.house-legend dd:last-child {
  margin-bottom: 0;
}

/* ── The sheet in the platen ───────────────────────────────────── */
.house-sheet {
  position: relative;
  padding: 2rem 2.25rem 2.25rem;
  background: var(--color-editor-bg);
  border: 1px solid var(--color-paper-3);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 22px 40px -32px rgb(0 0 0 / 0.55);
  animation: house-sheet-in 260ms ease-out;
}
@keyframes house-sheet-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}
@media (max-width: 640px) {
  .house-sheet {
    padding: 1.25rem 1rem 1.5rem;
  }
}
.house-sheet__kicker {
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-sheet__title {
  display: block;
  width: 100%;
  margin: 0.35rem 0 0.25rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 1.6rem/1.15 var(--font-display);
}
.house-sheet__title:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-sheet__lede {
  margin: 0 0 1.5rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-section {
  margin-top: 1.75rem;
}
.house-section:first-of-type {
  margin-top: 0;
}
.house-section__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.35rem;
  margin-bottom: 0.75rem;
  border-bottom: 1px solid var(--color-ink);
}
.house-section__title {
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
}
.house-section__note {
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Dossier fields: typed lines on a form. The source layer is stamped. */
.house-fields {
  display: flex;
  flex-direction: column;
}
.house-field {
  display: grid;
  grid-template-columns: 8.5rem 1fr;
  gap: 0.75rem;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--color-paper-3);
}
@media (max-width: 640px) {
  .house-field {
    grid-template-columns: 1fr;
    gap: 0.25rem;
  }
}
.house-field__label {
  padding-top: 0.3rem;
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-field__value {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  min-width: 0;
}
.house-input {
  width: 100%;
  padding: 0.25rem 0;
  border: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: var(--color-ink);
  font: 0.95rem/1.5 var(--font-typewriter);
  resize: none;
  field-sizing: content;
  min-height: 1.6rem;
}
.house-input::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.55;
  font-style: italic;
}
.house-input:hover {
  border-bottom-color: var(--color-paper-3);
}
.house-input:focus {
  outline: none;
  border-bottom-color: var(--color-vermilion);
}
.house-input[readonly] {
  cursor: default;
  border-bottom-color: transparent;
}
.house-inherit {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  font: 0.72rem/1.4 var(--font-serif);
  color: var(--color-ink-muted);
}
.house-inherit s {
  opacity: 0.7;
}
/* A layer stamp — the rubber stamp each field carries. */
.house-stamp {
  display: inline-block;
  padding: 0 0.3rem;
  border: 1.25px solid currentColor;
  border-radius: 2px;
  font: 0.54rem/1.5 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transform: rotate(-2deg);
  mix-blend-mode: multiply;
}
.house-stamp--house {
  color: var(--color-vermilion);
}
.house-stamp--collection {
  color: var(--color-mustard);
}
.house-stamp--folio {
  color: var(--color-cobalt);
}
.house-stamp--amendment {
  color: var(--color-writer-note);
}
.house-stamp--charter {
  color: var(--color-sage);
}

